import {CAMPUS as RAW} from './campus-data.js?v=26b79da8da82';
import {NEWTON_ID,newtonGeometry} from './physics-precinct-data.js?v=26b79da8da82';
import {framePoint,frameRectangle} from './geometry.js?v=26b79da8da82';
import {terrainHeight} from './terrain.js?v=26b79da8da82';
export const HELIUM_SOURCE='https://www.unsw.edu.au/estate/campus-development/projects/supporting-research-with-new-helium-infrastructure';
export const HELIUM_FRAME=newtonGeometry(RAW.buildings.find(b=>b.id===NEWTON_ID)).frame;
export const heliumPoint=(u,v)=>framePoint(HELIUM_FRAME,u,v);
export const heliumRectangle=(u0,u1,v0,v1)=>frameRectangle(HELIUM_FRAME,u1-u0,v1-v0,(u0+u1)/2,(v0+v1)/2);
export const heliumLocal=p=>({u:(p.x-HELIUM_FRAME.x)*HELIUM_FRAME.u.x+(p.z-HELIUM_FRAME.z)*HELIUM_FRAME.u.z,v:(p.x-HELIUM_FRAME.x)*HELIUM_FRAME.v.x+(p.z-HELIUM_FRAME.z)*HELIUM_FRAME.v.z});
const old=RAW.buildings.find(b=>b.id==='osm-way-45490050');
export const HELIUM_OLD_ANNEX={points:[old.points[6],old.points[7],old.points[8],old.points[9]],height:3.35,reconstructed:true};
export const HELIUM_BODIES=[{id:'newton-helium-metal',kind:'metal',u0:-8,u1:-1,v0:32.35,v1:40.1,height:6.4,opening:{u0:-5.5,u1:-1.9,bottom:0,top:2.9,depth:.15}},{id:'newton-helium-loading',kind:'grid',u0:-1,u1:5.4,v0:32.35,v1:40.1,height:6.2,opening:{u0:1.5,u1:4.9,bottom:0,top:3.1,depth:3.0}}].map(p=>({...p,points:heliumRectangle(p.u0,p.u1,p.v0,p.v1),reconstructed:true}));
export const HELIUM_WORK={points:heliumRectangle(-8.5,13.8,32.23,42.23),reconstructed:true};
export const HELIUM_FLOOR=Math.max(...HELIUM_BODIES.flatMap(b=>b.points).map(p=>terrainHeight(p.x,p.z)))+.22;
export const HELIUM_ANNEX_ROOF=HELIUM_FLOOR+HELIUM_OLD_ANNEX.height;
export const HELIUM_CHILLER={points:heliumRectangle(2.6,6.7,40.45,41.5),u:4.65,v:40.975,width:4.1,depth:1.05,height:2.05,reconstructed:true};
export const HELIUM_BED={points:heliumRectangle(-8,12.5,41.6,42.1),reconstructed:true};
export const HELIUM_SHRUBS=Array.from({length:14},(_,i)=>({...heliumPoint(-7.7+i*1.5,41.85),height:.85+(i%3)*.15,reconstructed:true}));
export const heliumField=p=>{const q=heliumLocal(p),t=Math.max(0,Math.min(1,(q.v-40.1)/(42.23-40.1)));return Math.max(terrainHeight(p.x,p.z)+.22,HELIUM_FLOOR+(terrainHeight(heliumPoint(q.u,42.23).x,heliumPoint(q.u,42.23).z)+.22-HELIUM_FLOOR)*t);};
const nearSegment=(p,a,c)=>{const dx=c.x-a.x,dz=c.z-a.z,t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.z-a.z)*dz)/(dx*dx+dz*dz)));return Math.hypot(p.x-a.x-dx*t,p.z-a.z-dz*t)<1e-6;};
export const heliumAnnexFace=(a,c)=>[0,.5,1].every(t=>{const p={x:a.x+(c.x-a.x)*t,z:a.z+(c.z-a.z)*t};return [[old.points[6],old.points[7]],[old.points[7],old.points[8]],[old.points[8],old.points[9]]].some(([a,c])=>nearSegment(p,a,c));});
export const inHeliumWork=(x,z)=>{const p=heliumLocal({x,z});return p.u>-8.5&&p.u<13.8&&p.v>32.23&&p.v<42.23;};
export const HELIUM_BUILDINGS=HELIUM_BODIES.map((b,i)=>({id:b.id,name:i?'Newton · enclosed loading dock':'Newton · helium recovery enclosure',points:b.points,holes:[],height:b.height,heightQuantity:'Enclosure above fitted slab',heightSource:'estimated',heightReference:{title:'UNSW completed project photographs',url:HELIUM_SOURCE,linkLabel:'Appearance source · UNSW'},heightNote:'Photo-fitted external addition beside Newton and Physics Lawn, listed among UNSW’s completed 2026 projects. Footprint, floor, component heights, cladding / portal details, equipment and landscaping are reconstructions, not measured as-built geometry. Existing Newton and Old Main source footprints / height tags and original path widths remain. Interior access is not offered.',levels:null,kind:'service',type:'academic',campusRef:'J12',campus:true,named:true,modelledWith:'newton-helium',reconstructed:true}));
const arrival=heliumPoint(-1,51),target=heliumPoint(-1,36.2);
export const HELIUM_VIEW={id:'newton-physics-lawn-loading',name:'Newton · Physics Lawn loading zone',code:'J12',kind:'viewpoint',...arrival,heading:Math.atan2(target.x-arrival.x,arrival.z-target.z),pitch:.14,showSign:false,description:'Silver horizontal cladding, grey grid-panel loading enclosure, closed roller door, green equipment box and young planting. UNSW completed-project photographs guide this addition; all fine dimensions and levels are fitted estimates. Original mapped building / path data stays separate'};
